// Normalizes the AIReceptionist webhook payload.
// Webhook node wraps the POSTed JSON in `body`; accept bare payloads too.
const b = $input.first().json;
const p = b.body ?? b;
return [{ json: {
  caller_name: p.message?.caller_name ?? "",
  caller_company: p.message?.caller_company ?? "",
  callback_number: p.message?.callback_number ?? "",
  caller_phone: p.message?.caller_phone ?? "",
  message: p.message?.message ?? "",
  business: p.message?.business_name ?? "",
  timestamp: p.message?.timestamp ?? "",
  call_id: p.context?.call_id ?? null
}}];
